def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0

    if not alive_opponents:
        solo_bid = 1.0
        if hp <= 2 or no_water_days >= 2:
            solo_bid = 8.0
        return min(budget, solo_bid)

    total_agents_alive = 1 + len(alive_opponents)
    tight_supply = supply <= total_agents_alive * WATER_REQ
    very_tight_supply = supply < total_agents_alive * WATER_REQ

    prev_bids = []
    desperate_opp = 0
    rich_opp = 0
    error_opp = 0
    for opp in alive_opponents:
        if opp.get('budget', 0) > budget:
            rich_opp += 1
        if opp.get('hp', 10) <= 2 or opp.get('no_water_days', 0) >= 2:
            desperate_opp += 1
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(bid)
        if prev.get('error'):
            error_opp += 1

    highest_prev = max(prev_bids) if prev_bids else None
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else None

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water_days >= 2:
        urgency += 3
    elif no_water_days == 1:
        urgency += 1

    if very_tight_supply:
        urgency += 2
    elif tight_supply:
        urgency += 1

    if desperate_opp >= max(1, len(alive_opponents) // 2):
        urgency += 1

    if day >= 8:
        urgency += 1

    if highest_prev is None:
        if urgency >= 6:
            bid = 64.0
        elif urgency >= 4:
            bid = 49.0
        elif urgency >= 2:
            bid = 34.0
        else:
            bid = 18.0 if tight_supply else 10.0
    else:
        if urgency >= 6:
            bid = max(63.0, highest_prev + 2.0)
        elif urgency >= 4:
            bid = max(48.0, highest_prev + 1.0)
        elif urgency >= 2:
            anchor = avg_prev if avg_prev is not None else highest_prev
            bid = max(30.0, anchor)
            if highest_prev <= 25:
                bid = highest_prev + 1.5
        else:
            if highest_prev >= 60:
                bid = 12.0 if hp > 3 else 58.0
            elif highest_prev >= 45:
                bid = 20.0 if not tight_supply else 32.0
            else:
                bid = max(12.0, highest_prev * 0.8)

    if error_opp > 0 and urgency <= 3:
        bid *= 0.9

    if rich_opp >= len(alive_opponents) and urgency <= 2:
        bid *= 0.85

    reserve = 0.0
    if day <= 3:
        reserve = 35.0
    elif day <= 6:
        reserve = 20.0
    else:
        reserve = 5.0

    max_affordable = budget - reserve
    if urgency >= 5:
        max_affordable = budget
    elif max_affordable < 0:
        max_affordable = 0.0

    bid = min(bid, max_affordable if max_affordable > 0 else budget)
    if hp <= 2 or no_water_days >= 2:
        bid = max(bid, min(budget, 60.0))

    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    budget = float(my_status.get('budget', 0.0))
    hp = float(my_status.get('hp', 0.0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        return min(budget, DAILY_SALARY * 0.4)

    # Read yesterday bids from traces
    prev_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # If no trace info, bid based on our hp
    if not prev_bids:
        if hp <= 2:
            return min(budget, DAILY_SALARY * 0.9)
        return min(budget, DAILY_SALARY * 0.55)

    highest_prev_bid = max(prev_bids)

    # Estimate how many full requirements the supply can cover
    # (use int() for any list indexing; here only for comparisons)
    max_full = int(supply / float(WATER_REQ)) if WATER_REQ > 0 else 0

    # Aggressive if opponents were bidding very high yesterday
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # If we are low hp, push harder.
        if hp <= 2:
            target = DAILY_SALARY * 0.95
        elif hp <= 3:
            target = DAILY_SALARY * 0.75
        else:
            target = DAILY_SALARY * 0.65
        # Slightly outbid the previous max to steal allocation
        target = max(target, highest_prev_bid + 1.0)
    else:
        # Moderate: compete but preserve budget
        # If supply is tight, raise bid; if abundant, lower.
        tightness = 0.0
        if max_full <= 1:
            tightness = 1.0
        elif max_full == 2:
            tightness = 0.6
        else:
            tightness = 0.3

        base = max(DAILY_SALARY * 0.45, highest_prev_bid + 1.5)
        target = base + tightness * (DAILY_SALARY * 0.15)

    # Final cap by budget and a minimum floor to avoid zeroing out when competing
    target = float(target)
    if budget <= 0:
        return 0.0

    # Ensure we never exceed budget
    bid = min(budget, target)

    # If our hp is critical, don't be too conservative
    if hp <= 1 and bid < DAILY_SALARY * 0.6:
        bid = min(budget, DAILY_SALARY * 0.85)

    return float(bid)
